wn in A and B tower pages 5-17; historical documented office configuration"},{"lib":"5c28eb30-c31b-5f82-a906-67b3d4cb226b","pg":5,"hash":"c3d9549d31110de6487b024aec1842ab85a63f53cc930997e3d7088b1e2a6a4d","f":"raised_floor_cm","type":"integer","unit":"cm","pat":"网络地板：([0-9]+) cm","note":"same specification shown in A and B tower pages 5-17; historical documented office configuration"},{"lib":"d2a705c7-1a4a-5794-8e8c-a5094049a56d","pg":5,"hash":"84de15a1a7cda3355d62078bc8514ee4a086271364bdb4425139635971bdb0a0","f":"metro_access","type":"text","unit":"nearby_lines","pat":"(距离地铁17号线红军营站仅600米[[:space:]]+毗邻13号线北苑站及5号线北苑路北站)","note":"brochure-reported distances, not new route survey"}]$spec$::jsonb) v(lib uuid,pg int,f text,type text,unit text,pat text,hash text,note text)),
fact_specs AS (SELECT * FROM jsonb_to_recordset($spec$[{"src":"844ba62e-c79a-45dc-8412-509d6479aa03","hash":"ea820b98c359ba8d91e23b49cd48a029152ae2cfbadad7e00bf55088458a02fa","label":"Z3东环捌号（CBD核心区Z3项目） · P35/1","f":"gfa_total","type":"numeric","unit":"m2","pat":"总建面约([0-9.]+)万㎡","mult":10000,"note":"future supply; approximate historical design total GFA (not office or leasable area); corroborated by other reviewed Z3 version"},{"src":"844ba62e-c79a-45dc-8412-509d6479aa03","hash":"ea820b98c359ba8d91e23b49cd48a029152ae2cfbadad7e00bf55088458a02fa","label":"Z3东环捌号（CBD核心区Z3项目） · P35/3","f":"efficiency_rate","type":"numeric","unit":"percent","pat":"标准层使用率约([0-9]+)%","mult":1,"note":"future supply; approximate design standard-floor efficiency, not as-built measurement"},{"src":"51c41d6a-0a62-4531-a195-ae76cd0e27a2","hash":"08c4fb35fb4490f3edaf51813ae27c46f23dd8aebd1dc30965f0a61d6b48a825","label":"Z3东环捌号（CBD核心区Z3项目） · P35/3","f":"telecom_provider","type":"text","unit":"provider_names","pat":"原页列(联通、电信、移动)三家","mult":1,"note":"future supply historical planned telecom provision, not claim of active service"},{"src":"413df196-ed04-41c9-a2e6-8833765bbced","hash":"bc42d3b56e44074a1cb205e9c274b7c7aeaacef4b1b8340c0f874e02b89ba231","label":"Vision Place维晟中心（远洋Z6） · P12/1","f":"well_certification","type":"text","unit":"historical_certification_label","pat":"(WELL中期认证)","mult":1,"note":"future supply; interim certification as archived, not final certification or independently checked current status"},{"src":"c9a2fb6b-ceb0-5272-836b-11c9dacc6ea8","hash":"3672335053df0af61c8b52ae4c5cc25c8576b2523d18c1b68b234b312d476cea","label":"国家金融信息大厦功能方案 · 原文参数1","f":"elevator_zones","type":"text","unit":"configuration","pat":"(高/中/次低/低区共28主客梯，摆渡2×2另计)","mult":1,"note":"reviewed historical design; main passenger count agrees with existing 28, transfer elevators distinct"}]$spec$::jsonb) v(src uuid,hash text,label text,f text,type text,unit text,pat text,mult numeric,note text)),
a AS (SELECT a.*,a.details->>'field_name' field_name,a.details->>'source_kind' source_kind,a.details->>'source_table' source_table,(a.details->>'source_record_id')::uuid source_id,a.details->>'source_field' source_field,(a.details->>'building_id')::uuid building_id,(a.details->>'evidence_group_id')::uuid evidence_id FROM public.audit_logs a WHERE a.action_type='AI_FIELD_FILL' AND a.details->>'batch_ref'='ai_building_field_backfill_20261124_v4_100'),
checked AS (
SELECT a.*,b.project_type,d.id brochure_id,to_jsonb(d)->a.field_name actual,p.id provenance_id,p.field_value provenance_value,p.is_current,p.source_type,p.verification_status,p.evidence_note,
(SELECT count(*) FROM public.building_data_field_provenance z WHERE z.building_id=a.building_id AND z.target_table=a.target_table AND z.field_name=a.field_name AND z.is_current) current_sources,
CASE
 WHEN a.source_kind='internal_calculation' AND a.source_id=d.id THEN to_jsonb(d.parking_total-d.parking_underground)
 WHEN a.source_kind='internal_field_extraction' AND a.source_id=d.id THEN to_jsonb(CASE WHEN d.power_system LIKE '市政双路供电，%' THEN split_part(d.power_system,'，',1) ELSE d.power_system END)
 WHEN a.source_kind IN ('internal_catalog_sync','internal_future_catalog_sync') AND a.source_id=b.id THEN to_jsonb(b)->a.source_field
 WHEN a.source_kind='internal_archived_page' THEN (SELECT CASE s.type WHEN 'numeric' THEN to_jsonb(m.val::numeric) WHEN 'integer' THEN to_jsonb(m.val::integer) WHEN 'boolean' THEN to_jsonb(true) ELSE to_jsonb(trim(regexp_replace(m.val,'[[:space:]]+',' ','g'))) END FROM page_specs s JOIN public.project_material_library l ON l.id=s.lib JOIN public.project_material_library_pages pg ON pg.extraction_id=s.lib AND pg.page_number=s.pg AND pg.content_sha256=s.hash CROSS JOIN LATERAL (SELECT (regexp_match(pg.content->>'native_text',s.pat))[1] val) m WHERE s.lib=a.source_id AND 'page:'||s.pg=a.source_field AND s.f=a.field_name AND m.val IS NOT NULL AND l.review_state='reviewed' AND p.evidence_note LIKE '%page_sha256='||s.hash||'%' AND EXISTS(SELECT 1 FROM jsonb_array_elements(l.payload->'sections') sec WHERE sec->>'association_status'='confirmed' AND sec->'candidate_building_ids' ? a.building_id::text))
 WHEN a.source_kind='internal_project_fact' THEN (SELECT CASE WHEN s.type='numeric' THEN to_jsonb(m.val::numeric*s.mult) ELSE to_jsonb(m.val) END FROM fact_specs s JOIN public.building_sales_materials mat ON mat.id=s.src AND mat.source_sha256=s.hash CROSS JOIN LATERAL jsonb_array_elements(mat.project_facts) x CROSS JOIN LATERAL (SELECT (regexp_match(x->>'value',s.pat))[1] val) m WHERE s.src=a.source_id AND s.label=a.source_field AND s.f=a.field_name AND mat.building_id=a.building_id AND mat.status='ready' AND mat.association_status='confirmed' AND mat.extraction->'extraction'->>'reviewed'='true' AND x->>'label'=s.label AND m.val IS NOT NULL AND p.evidence_note LIKE '%source_sha256='||s.hash||'%')
END source_value
FROM a LEFT JOIN public.building_brochure_data d ON d.id=a.target_id::uuid AND d.building_id=a.building_id LEFT JOIN public.buildings b ON b.id=a.building_id LEFT JOIN public.building_data_field_provenance p ON p.evidence_group_id=a.evidence_id AND p.brochure_data_id=d.id AND p.building_id=b.id AND p.target_table=a.target_table AND p.field_name=a.field_name
)
SELECT count(*) audit_rows,count(distinct (target_table,target_id,field_name)) unique_fields,count(distinct building_id) building_count,count(distinct field_name) field_types,count(distinct provenance_id) matched_provenance,count(*) FILTER (WHERE is_current AND current_sources=1) sole_current_provenance,count(*) FILTER (WHERE old_values->field_name='null'::jsonb AND actual IS NOT NULL AND actual<>'null'::jsonb AND actual=new_values->field_name AND actual=provenance_value AND is_current AND current_sources=1 AND actor_kind='tool' AND user_id='codex' AND details->>'ai_assisted'='true' AND verification_status='legacy_backfill' AND evidence_note LIKE '%batch_ref=ai_building_field_backfill_20261124_v4_100;%' AND evidence_note LIKE '%source_record_id='||source_id::text||';%') fully_verified,
count(*) FILTER (WHERE source_value IS NOT NULL AND source_value<>'null'::jsonb AND source_value=actual) source_value_verified,
(SELECT count(*) FROM public.building_data_field_provenance WHERE evidence_note LIKE 'batch_ref=ai_building_field_backfill_20261124_v4_100;%' AND is_current) batch_current_sources,
(SELECT count(*) FROM public.audit_logs WHERE action_type='AI_FIELD_ROLLBACK' AND details->>'rollback_batch_ref'='ai_building_field_backfill_20261124_v4_100_rollback') persistent_rollbacks,
(SELECT jsonb_object_agg(field_name,n ORDER BY field_name) FROM (SELECT field_name,count(*) n FROM a GROUP BY 1) f) fields,
(SELECT jsonb_object_agg(source_kind,n) FROM (SELECT source_kind,count(*) n FROM a GROUP BY 1) s) sources,
(SELECT jsonb_object_agg(project_type,n) FROM (SELECT project_type,count(*) n FROM checked GROUP BY 1) s) project_types,
(SELECT jsonb_object_agg(project_type,n) FROM (SELECT project_type,count(distinct building_id) n FROM checked GROUP BY 1) s) building_types,
(SELECT jsonb_object_agg(sub_batch,n) FROM (SELECT details->>'sub_batch' sub_batch,count(*) n FROM a GROUP BY 1) s) batches
FROM checked;